    mut tree: *mut ct_data,
    mut max_code: c_int,
    mut bl_count: *mut ushf,
) {
    let mut next_code: [ush; 16] = [0; 16];
    let mut code: c_uint = 0 as c_uint;
    let mut bits: c_int = 0;

    // SAFETY: `bl_count` is read for indices 0..=MAX_BITS-1 in this loop; by caller
    // contract it points to a valid count table covering those entries, is non-null,
    // and no Rust reference aliases that memory for the duration of this view.
    let bl_count = unsafe { core::slice::from_raw_parts(bl_count, MAX_BITS as usize) };
    // SAFETY: the loop walks tree entries 0..=max_code; by caller contract `tree`
    // points to at least `max_code + 1` contiguous `ct_data` entries, is non-null,
    // and no other Rust reference aliases that region while this mutable view is live.
    let tree = unsafe { core::slice::from_raw_parts_mut(tree, max_code.wrapping_add(1) as usize) };

    bits = 1 as c_int;
    while bits <= MAX_BITS {
        code = code.wrapping_add(bl_count[(bits - 1 as c_int) as usize] as c_uint) << 1 as c_int;
        next_code[bits as usize] = code as ush;
        bits += 1;
    }

    for node in tree.iter_mut() {
        let len: c_int = unsafe { node.dl.len as c_int };
        if len != 0 as c_int {
            // SAFETY: nonzero code lengths in `tree` satisfy the deflate invariant
            // `1 <= len <= MAX_BITS`, and `next_code` has length 16 with indices 0..=15,
            // so `len as usize` is in-bounds here.
            let slot = unsafe { next_code.get_unchecked_mut(len as usize) };
            let code_for_len = *slot;
            *slot = slot.wrapping_add(1);
            unsafe { node.fc.code = bi_reverse(code_for_len as c_uint, len) as ush };
        }
    }
